def shortest(N, edgeList):
    # Initialize distance array with infinity
    dist = [float('inf')] * N
    dist[0] = 0

    # Process nodes in topological order (since start < end, we can process in order 0..N-1)
    for u in range(N):
        if dist[u] == float('inf'):
            continue  # Skip unreachable nodes
        for edge in edgeList:
            if edge[0] == u:
                v, weight = edge[1], edge[2]
                if dist[v] > dist[u] + weight:
                    dist[v] = dist[u] + weight

    return dist[N-1] if dist[N-1] != float('inf') else -1
